nodes.script:
var out=[];var seen={};
var A=document.querySelectorAll("a[href]");
for(var i=0;i<A.length;i++){
  var hh=A[i].getAttribute("href")||"";
  if(hh.indexOf("/issues/")<0) continue;
  var part=(hh.split("/issues/")[1]||"").split("#")[0].split("?")[0];
  if(!part||isNaN(Number(part))) continue;
  if(seen[hh])continue; seen[hh]=1;
  var t=(A[i].innerText||"").replace(/s+/g," ").trim();
  if(t.length<6) continue;
  out.push({number:Number(part),title:t});
  if(out.length>=20) break;
}
return out;
